CREATE TABLE crop_market_data(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`crop_name` varchar(255)  NOT NULL,`state` varchar(255)  NOT NULL,`district` varchar(255)  NULL,`price_per_kg` DECIMAL(10,2)  NOT NULL,`date` date  NOT NULL,`season` varchar(255)  NOT NULL COMMENT 'kharif, rabi, zaid',`yoy_growth` DECIMAL(5,2)  NULL COMMENT 'Year over year growth percentage',`demand_level` varchar(255)  NULL COMMENT 'high, medium, low')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;